  KEY `idx_repo_full_name` (`repo_full_name`),
  KEY `idx_language` (`language`),
  KEY `idx_stars` (`stars`),
  KEY `idx_topics` (`topics`),
  KEY `idx_fetched_at` (`fetched_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
